//! AI module B — embedded LLM prompt-artifact scanner.
//!
//! A growing class of malware carries LLM instructions, chat-API request
//! scaffolding, provider endpoints, or API keys embedded as strings — either
//! to call a model at runtime or because it was itself generated by one. This
//! scanner looks for those artifacts in a byte buffer (a file on disk, or,
//! later, a memory region handed over by the memory-scan path).
//!
//! It runs in Rust because it eats hostile input: arbitrary malware samples,
//! truncated binaries, deliberately malformed data. Memory safety means a bad
//! sample can produce a wrong answer but not memory corruption; a panic is
//! caught in main.rs and returned as an error line.
//!
//! Matching is binary-safe (`regex::bytes`, ASCII mode) and runs over three
//! views of the input: the raw bytes (ASCII/UTF-8), and the UTF-16LE strings
//! at even and odd offsets — Windows binaries and .NET assemblies store most
//! string literals as UTF-16LE, which a byte-oriented pattern would miss.

use crate::contract::{Hit, Response};
use regex::bytes::{Regex, RegexSet};
use serde_json::json;
use std::collections::BTreeMap;
use std::fs::File;
use std::io::Read;
use std::sync::LazyLock;

/// Max bytes to scan from a single file. Caps memory use on a hostile oversized
/// input; larger files are scanned up to the cap and flagged as truncated.
pub const MAX_SCAN: usize = 64 * 1024 * 1024;

/// Bytes of context shown either side of a match.
const PAD: usize = 16;
/// Characters of a secret left visible (enough to tell the key type).
const SECRET_SHOW: usize = 6;
/// How far around a context window to look for secrets to redact.
const SECRET_REACH: usize = 256;

/// What a random key body must contain to count as a key.
#[derive(Clone, Copy, PartialEq, Eq)]
enum KeyAlphabet {
    /// Digits and both letter cases (base62/base64-style keys).
    Mixed,
    /// Digits and letters (lower-case hex keys).
    Hex,
}

/// Extra checks for API-key rules, applied to each regex match.
#[derive(Clone, Copy)]
struct Secret {
    /// Fixed prefix length; the random-looking body starts after it.
    prefix: usize,
    /// Reject matches starting with this (lets the generic `sk-` rule leave
    /// Anthropic and OpenRouter keys to their own rules without hiding real
    /// OpenAI keys).
    not_starting_with: &'static [&'static [u8]],
    alphabet: KeyAlphabet,
}

struct Def {
    rule: &'static str,
    severity: &'static str,
    technique: &'static str,
    weight: i64,
    secret: Option<Secret>,
    pattern: &'static str,
}

